Programa2 (supuesto 2008, en C):
#include <stdio.h>
#include <stdlib.h>
void swap1 (char *a1, char *a2){
  char *aux;
  aux=a1;
  a1=a2;
  a2=aux;
}
void swap2 (char **a1, char **a2){
  char **aux;
  *aux=*a1;
  *a1=*a2;
  *a2=*aux;
}
int main(int nargs, char *args[]){
  printf("Orden 1\n");
  for (int i=1;i<nargs-1;i++)
    for (int j=i+1;j<nargs;j++)
      if (atoi(args[i])<atoi(args[j])) swap1(args[i],args[j]);
  for (int i=1;i<nargs;i++) printf("%3s",args[i]);
  printf("\nOrden 2\n");
  for (int i=1;i<nargs-1;i++)
    for (int j=i+1;j<nargs;j++)
      if (atoi(args[i])>atoi(args[j])) swap2(&args[i],&args[j]);
  for (int i=1;i<nargs;i++) printf("%3s",args[i]);
  printf("\n");
}

Programa SERIE (supuesto 2008, Java):
public void Serie (int [] entrada) {
  int [] salida = new int[entrada.length];
  int suma;
  for (int i=0; i<entrada.length; i++) {
    suma = 0;
    for (int j=i; j<entrada.length; j++) {
      suma += entrada[j];
    }
    salida[i] = suma;
  }
  for (int i=0; i<salida.length; i++)
    System.out.print(" "+salida[i]+", ");
}

