public static int getFilas (int [][] matriz) { if (matriz == null) return -1; return matriz.length; }
public static int getColumnas (int [][] matriz) { if (matriz == null) return -1; return matriz[0].length; }
public static int[][] Matriz (int[][] A) {
  if (A==null) return null;
  int[][] algo = new int [getColumnas(A)][getFilas(A)];
  for (int i=0; i<getColumnas(A); i++)
    for (int j=0; j<getFilas(A); j++)
      algo[i][j] = A[j][i];
  return algo;
}

